// Prelumo dashboard strategy - generated by the integration (custom:prelumo).
// The backend passes the entity ids in the strategy config; views are built here.

const md = (content, extra = {}) => ({ type: "markdown", content, grid_options: { columns: "full" }, ...extra });
const tile = (entity, name, columns = 6, extra = {}) => ({ type: "tile", entity, name, grid_options: { columns }, ...extra });

function planView(E, I) {
  const P = E.proposed_plan, A = E.active_slot;
  const slots = `{%- set ic = {'none':'🏠','grid_charge':'🔌','sell':'💰'} -%}
{%- set cur = state_attr('${A}','slots') or [] -%}
{%- set pro = state_attr('${P}','slots') or [] -%}
{%- set act = state_attr('${A}','slot') -%}
{%- set kc = state_attr('${P}','current_slot_costs') or [] -%}
{%- set kp = state_attr('${P}','slot_costs') or [] -%}
{%- macro zl(v) -%}{{ ('%.2f zł' % v) if v is not none else '–' }}{%- endmacro -%}
| # | Falownik teraz | Moc | Koszt | Prelumo proponuje | Moc | Koszt |
|:-:|:--|--:|--:|:--|--:|--:|
{% for i in range(6) -%}
{%- set c = cur[i] if cur | count > i else none -%}
{%- set q = pro[i] if pro | count > i else none -%}
{%- set on = act is not none and act == i + 1 -%}
| {{ ('▶️ ' if on else '') ~ (i + 1) }} | {{ (('**' if on else '') ~ c.start ~ ' ' ~ ic.get(c.mode,'') ~ ' ' ~ c.soc ~ '%' ~ ('**' if on else '')) if c else '–' }} | {{ ('%.1f kW' % (c.power / 1000)) if c else '–' }} | {{ zl(kc[i] if kc | count > i else none) }} | {{ (q.start ~ ' ' ~ ic.get(q.mode,'') ~ ' ' ~ q.soc ~ '%') if q else '–' }} | {{ ('%.1f kW' % (q.power / 1000)) if q else '–' }} | {{ zl(kp[i] if kp | count > i else none) }} |
{% endfor -%}
{%- set sc = kc | reject('none') | sum -%}{%- set sp = kp | reject('none') | sum -%}
| | **Razem w oknie {{ state_attr('${P}','slot_window_hours') }} h** | | **{{ zl(sc) if kc else '–' }}** | | | **{{ zl(sp) if kp else '–' }}** |

Tryb pracy teraz: **{{ states('${I.mode_select}') }}** · Prelumo chce: **{{ state_attr('${A}','desired_mode') or '–' }}** · następna zmiana {{ as_timestamp(states('${E.next_change}')) | timestamp_custom('%H:%M') if states('${E.next_change}') not in ['unknown','unavailable'] else '–' }}

🏠 bateria zasila dom do progu SoC · 🔌 ładowanie z sieci do SoC · 💰 sprzedaż do SoC · Moc = limit całej mocy baterii w slocie (w 💰 także dla domu) · Koszt = zakup − sprzedaż + zużycie baterii w godzinach slotu w oknie planu (ujemny = zarobek; – = slot poza oknem)`;

  const hourly = `{%- set ic = {'normal':'🏠','grid_charge':'🔌','sell':'💰'} -%}
{%- set h = state_attr('${P}','slot_hourly') or [] -%}
{%- set cur = state_attr('${P}','current_hourly') or [] -%}
{%- if not h -%}Brak danych.{%- else -%}
Harmonogram z 6 slotów, tak jak wykona go falownik, w oknie **{{ state_attr('${P}','slot_window_hours') }} h**.

| Godz. | Slot | Próg | SoC | SoC teraz* | Zużycie | PV | Z baterii | Pobór | Oddanie | Zakup | RCE | Koszt |
|:--|:-:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|--:|
{% for r in h -%}
{%- set i = loop.index0 -%}
| {{ r.start[11:16] }} | {{ ic.get(r.mode,'') }} | {{ r.floor }}% | **{{ r.soc }}%** | {{ (cur[i].soc ~ '%') if cur | count > i else '–' }} | {{ '%.1f' % (r.load + r.ev) }}{{ ' 🚗' if r.ev > 0.05 else '' }} | {{ '%.1f' % r.pv }} | {{ '%.1f' % r.battery }} | {{ '%.1f' % r['import'] }} | {{ '%.1f' % r.export }} | {{ '%.2f' % r.buy }} | {{ '%.2f' % r.sell }} | {{ '%.2f' % r.cost }} |
{% endfor %}
kWh/h · koszt w zł (ujemny = zarobek) · \\* SoC teraz = przebieg na harmonogramie, który jest teraz w falowniku
{%- endif %}`;

  return {
    title: "Plan", path: "plan", icon: "mdi:calendar-clock", type: "sections", max_columns: 3,
    sections: [
      {
        type: "grid", column_span: 2, cards: [
          {
            type: "heading", heading: "Harmonogram falownika", icon: "mdi:calendar-clock",
            badges: [{
              type: "button", icon: "mdi:upload", text: "Zapisz plan teraz", color: "orange",
              tap_action: {
                action: "perform-action", perform_action: "prelumo.replan", data: { write: true },
                confirmation: { text: "Przeliczyć plan i od razu zapisać harmonogram do falownika? (pomija limity zapisów; nie zapisze, jeśli plan się nie zmienił)" },
              },
            }],
          },
          md(slots),
          { type: "heading", heading: "Co zrobi falownik — godzina po godzinie", heading_style: "subtitle", icon: "mdi:table-clock" },
          md(hourly),
        ],
      },
      {
        type: "grid", cards: [
          { type: "heading", heading: "Teraz", icon: "mdi:battery-clock" },
          tile(I.soc, "SoC"), tile(I.battery_power, "Bateria"),
          tile(I.grid_power, "Sieć"), tile(I.house, "Dom"),
          tile(I.mode_select, "Tryb pracy", 12, { features: [{ type: "select-options" }] }),
          tile(E.auto_mode, "Sterowanie Prelumo"), tile(E.sell_now, "Sprzedaż teraz"),
          { type: "heading", heading: "Ostatnie 24 h", heading_style: "subtitle", icon: "mdi:chart-line" },
          { type: "history-graph", hours_to_show: 24, entities: [{ entity: I.soc, name: "SoC", color: "green" }], grid_options: { columns: "full", rows: 3 } },
          {
            type: "history-graph", hours_to_show: 24, grid_options: { columns: "full", rows: 4 },
            entities: [
              { entity: I.battery_power, name: "Bateria (+ rozładowanie)", color: "orange" },
              { entity: I.grid_power, name: "Sieć (+ pobór, − oddanie)", color: "blue" },
            ],
          },
        ],
      },
    ],
  };
}

function decisionsView(E, I) {
  const P = E.proposed_plan, A = E.active_slot, F = E.last_full_charge;
  const decisions = `{%- set fmt = '%d.%m %H:%M' %}
### Decyzje
- **Tryb pracy teraz:** {{ states('${I.mode_select}') }} · **Prelumo chce:** {{ state_attr('${A}','desired_mode') or '–' }} ({{ state_attr('${A}','mode_action') or '–' }})
- **Przeliczono:** {{ as_timestamp(state_attr('${P}','computed_at')) | timestamp_custom(fmt) if state_attr('${P}','computed_at') else '–' }} (co godzinę o :03)

#### Zapis do falownika
{%- set wd = state_attr('${P}','write_decision') or [] %}
{%- set why = {'no_material_change':'✅ falownik ma już ten plan (brak istotnej zmiany)','gain_below_threshold':'⏸ nowy plan nie jest wyraźnie tańszy od obecnego','daily_write_limit':'⏸ wyczerpany dzienny limit zapisów','write_budget_paced':'⏸ drobna zmiana — limit zapisów rozłożony na dobę (zapas na później)','min_interval':'⏸ za krótko od poprzedniego zapisu','shadow_mode':'⏸ tryb cienia — nic nie zapisuje','auto_mode_off':'⏸ tryb automatyczny wyłączony','write_failed':'❌ zapis nieudany','change_far_ahead':'⏸ zmiana dopiero za ≥ 12 h — poczeka na kolejne przeliczenia','proposal_breaks_rules':'⏸ nowy plan łamie regułę, której obecny nie łamie','urgent_rule_fix':'⚡ zapisano od razu — obecny plan łamie regułę w ciągu 3 h'} %}
- **Ostatnia decyzja:** {{ why.get(wd[0], '✅ zapisano nowy plan') if wd else '–' }}{{ (' (' ~ wd[1] ~ ' zł)') if wd and wd[0] == 'gain_below_threshold' else '' }}
- **Ostatni zapis:** {{ as_timestamp(state_attr('${P}','last_write')) | timestamp_custom(fmt) if state_attr('${P}','last_write') else 'brak' }}
{%- set wt = state_attr('${P}','writes_today') or [] %}
- **Zapisy dziś:** {{ wt | count }} z {{ state_attr('${P}','max_writes_per_day') }}{{ (' — ' ~ (wt | map('as_timestamp') | map('timestamp_custom','%H:%M') | join(', '))) if wt else '' }} · teraz dozwolone drobne: {{ state_attr('${P}','write_budget_now') or '–' }}
{%- set nx = as_timestamp(state_attr('${P}','next_write_allowed'), 0) %}
- **Następny zapis możliwy:** {{ 'teraz' if nx <= as_timestamp(now()) + 60 else (nx | timestamp_custom(fmt)) }}

#### Plan
- **Bateria 100%:** {{ ('ostatnio ' ~ (as_timestamp(states('${F}')) | timestamp_custom(fmt))) if states('${F}') not in ['unknown','unavailable'] else 'brak w historii' }} · co {{ state_attr('${F}','interval_days') }} dni · {{ ('teraz należne — ' ~ ('zaplanowane ✅' if state_attr('${F}','planned') else 'nie mieści się w planie ⚠️')) if state_attr('${F}','due') else 'nie należne' }}
{%- set evs = (state_attr('${F}','charge_events') or [])[-5:] %}
{%- set ns = namespace(m=[]) %}{%- for e in evs %}{%- if e.minutes['99'] is defined %}{%- set ns.m = ns.m + [e.minutes['99'] | round(0) | int] %}{%- endif %}{%- endfor %}
- **Ostatni 1% (99→100%):** {{ ('planowane ' ~ (ns.m | max) ~ ' min (najdłuższe z ' ~ (ns.m | count) ~ ' ostatnich ładowań: ' ~ (ns.m | join(', ')) ~ ' min)') if ns.m else 'jeszcze nie zmierzone — przyjęte ~30 min' }}
- **Koszt w oknie {{ state_attr('${P}','slot_window_hours') }} h — plan / obecny w falowniku / bez Prelumo:** {{ state_attr('${P}','expected_cost') }} / {{ state_attr('${P}','current_plan_cost') if state_attr('${P}','current_plan_cost') is not none else '–' }} / {{ state_attr('${P}','baseline_cost') }} zł
{%- set g = state_attr('${P}','gain_vs_current') %}
- **Zysk vs obecny:** {{ ('obecny łamie reguły — do wymiany' if g > 1000 else (g ~ ' zł')) if g is not none else '–' }}
{%- set ci = state_attr('${P}','current_plan_issues') or [] %}{%- set pi = state_attr('${P}','expected_issues') or [] %}
{%- if ci %}
- **Obecny w falowniku łamie:** {{ ci | join(', ') }}
{%- endif %}
{%- if pi %}
- **Plan łamie:** ⚠️ {{ pi | join(', ') }}
{%- endif %}
{%- set st = state_attr('${P}','stale_sources') or [] %}
{%- if st %}

> ⚠️ Brak danych: {{ st | join(', ') }}
{%- endif %}
{%- set n = state_attr('${P}','notes') or [] %}
{%- if n %}
- **Uwagi:** {{ n | join(', ') }}
{%- endif %}
{%- if state_attr('${P}','error') %}

> ❌ {{ state_attr('${P}','error') }}
{%- endif %}`;

  return {
    title: "Prelumo", path: "prelumo", icon: "mdi:white-balance-sunny", type: "sections", max_columns: 3,
    sections: [
      {
        type: "grid", cards: [
          { type: "heading", heading: "Sterowanie", icon: "mdi:tune", badges: [{ type: "entity", entity: P, show_state: true }] },
          tile(E.strategy, "Strategia", 12, { features: [{ type: "select-options" }] }),
          tile(E.auto_mode, "Sterowanie"), tile(E.shadow_mode, "Tryb cienia"),
          tile(E.grid_arbitrage, "Arbitraż"), tile(E.fallback_active, "Plan awaryjny"),
          tile(E.expected_savings, "Oszczędność"), tile(E.shadow_savings, "Suma w cieniu"),
          tile(E.battery_energy_cost, "Koszt energii w baterii"),
          tile(E.self_sufficiency, "Autarkia 30 dni"), tile(E.battery_cycles, "Cykle baterii"),
          { type: "markdown", grid_options: { columns: 6 }, content:
            `{%- set c = state_attr('${E.battery_energy_cost}','break_even_sell_price') %}` +
            `{%- if c %}Sprzedaż opłacalna od **{{ '%.3f'|format(c) }} zł/kWh**` +
            `{%- if state_attr('${E.battery_energy_cost}','estimated') %} _(szacunek)_{% endif %}` +
            `{%- else %}Bateria pusta{%- endif %}` },
          tile(E.last_full_charge, "Ostatnie 100%"), tile(E.full_charge_due, "100% należne"),
          tile(E.grid_outage, "Awaria sieci"), tile(E.alert_charge, "Ładowanie awaryjne"),
          tile(E.next_change, "Następna zmiana"),
        ],
      },
      { type: "grid", column_span: 2, cards: [md(decisions)] },
      {
        type: "grid", column_span: 3, cards: [
          { type: "heading", heading: "Prognozy", icon: "mdi:crystal-ball" },
          tile(E.pv_forecast_corrected, "PV 24 h (skoryg.)", 4), tile(E.load_forecast, "Zużycie 24 h", 4),
          tile(E.ev_energy_needed, "Auto potrzebuje", 4),
          { type: "history-graph", hours_to_show: 72, entities: [{ entity: E.expected_savings, name: "Oczekiwana oszczędność" }], grid_options: { columns: "full", rows: 3 } },
        ],
      },
    ],
  };
}

function rceView(R) {
  if (!R.today) return null;
  const t = `{%- set d = state_attr('${R.today}','prices') or [] -%}
{%- set t = state_attr('${R.tomorrow || R.today}','prices') or [] -%}
{%- set jutro = (now() + timedelta(days=1)).strftime('%Y-%m-%d') -%}
{%- set t = t | selectattr('business_date','eq', jutro) | list -%}
{%- set ad = d | map(attribute='rce_pln') | list -%}{%- set at = t | map(attribute='rce_pln') | list -%}
{%- set sd = (ad | sum / ad | count) if ad else 0 -%}{%- set sj = (at | sum / at | count) if at else 0 -%}
{%- set h = now().strftime('%H') -%}
{%- macro kol(v, s) -%}{{ '🟢' if v < s * 0.8 else ('🔴' if v > s * 1.2 else '🟡') }} {{ '%.2f' % v }}{%- endmacro -%}
| Godzina | Dziś {{ now().strftime('%d.%m') }} | Jutro {{ (now() + timedelta(days=1)).strftime('%d.%m') }} |
|:--|--:|--:|
{% for i in range(24) -%}
{%- set g = '%02d' % i -%}
{%- set a = d | selectattr('period','match', g ~ ':') | map(attribute='rce_pln') | list -%}
{%- set b = t | selectattr('period','match', g ~ ':') | map(attribute='rce_pln') | list -%}
{%- set va = kol(a | sum / a | count, sd) if a else '–' -%}
{%- set vb = kol(b | sum / b | count, sj) if b else '–' -%}
{%- if g == h -%}
| **▶️ {{ g }}:00** | **{{ va }}** | {{ vb }} |
{% else -%}
| {{ g }}:00 | {{ va }} | {{ vb }} |
{% endif -%}
{%- endfor %}
**Średnia:** dziś {{ '%.2f' % sd }} zł/kWh{{ (' · jutro %.2f zł/kWh' % sj) if t else ' · ceny na jutro jeszcze niedostępne (zwykle po ~14:00)' }}

🟢 < 80% średniej · 🟡 typowa · 🔴 > 120% średniej`;
  return {
    title: "Ceny RCE", path: "ceny-rce", icon: "mdi:cash-clock", type: "sections", max_columns: 2,
    sections: [{ type: "grid", column_span: 2, cards: [{ type: "heading", heading: "Ceny RCE – średnie godzinowe", icon: "mdi:cash-clock" }, md(t)] }],
  };
}

function editView(E, S) {
  if (!S || !S.length) return null;
  const A = E.active_slot;
  const rows = S.map((x, i) => `{% set c = cur[${i}] if cur | count > ${i} else none -%}
{% set d = (states('${x.start}')[:5], states('${x.mode}'), states('${x.soc}') | int(0), states('${x.power}') | float(0)) -%}
{% set diff = c and (c.start != d[0] or c.mode != d[1] or c.soc != d[2] or (c.power / 1000) | round(1) != d[3] | round(1)) -%}
| ${i + 1} | {{ (c.start ~ ' ' ~ ic.get(c.mode,'') ~ ' ' ~ c.soc ~ '% · ' ~ '%.1f' % (c.power / 1000) ~ ' kW') if c else '–' }} | {{ '**' if diff else '' }}{{ d[0] ~ ' ' ~ ic.get(d[1],'') ~ ' ' ~ d[2] ~ '% · ' ~ '%.1f' % d[3] ~ ' kW' }}{{ '** ✏️' if diff else '' }} |`).join("\n");
  const summary = `{%- set ic = {'none':'🏠','grid_charge':'🔌','sell':'💰'} -%}
{%- set cur = state_attr('${A}','slots') or [] -%}
| # | W falowniku | Szkic |
|:-:|:--|:--|
${rows}

✏️ = zmienione względem falownika. Slot trwa do startu następnego, ostatni do startu pierwszego. Starty muszą rosnąć.
{%- if is_state('${E.auto_mode}', 'on') %}

> ⚠️ **Sterowanie Prelumo jest włączone** — przy kolejnym przeliczeniu (co godzinę) Prelumo może zastąpić ręczny harmonogram swoim planem. Żeby został, wyłącz „Sterowanie”.
{%- endif %}`;
  const slotSection = (x, i) => ({
    type: "grid", cards: [
      { type: "heading", heading: `Slot ${i + 1}`, heading_style: "title" },
      tile(x.start, "Start", 12),
      tile(x.mode, "Tryb", 12, { features: [{ type: "select-options" }] }),
      tile(x.soc, "SoC", 12, { features: [{ type: "numeric-input", style: "buttons" }], features_position: "inline" }),
      tile(x.power, "Moc", 12, { features: [{ type: "numeric-input", style: "buttons" }], features_position: "inline" }),
    ],
  });
  return {
    title: "Edycja", path: "edycja", icon: "mdi:pencil", type: "sections", max_columns: 3,
    sections: [
      {
        type: "grid", column_span: 3, cards: [
          {
            type: "heading", heading: "Ręczna edycja harmonogramu", icon: "mdi:pencil",
            badges: [
              { type: "button", icon: "mdi:download", text: "Wczytaj z falownika", tap_action: { action: "perform-action", perform_action: "button.press", target: { entity_id: E.draft_load } } },
              { type: "button", icon: "mdi:upload", text: "Zapisz do falownika", color: "orange", tap_action: { action: "perform-action", perform_action: "button.press", target: { entity_id: E.draft_write }, confirmation: { text: "Zapisać ten harmonogram do falownika?" } } },
            ],
          },
          md(summary),
        ],
      },
      ...S.map(slotSection),
    ],
  };
}

class PrelumoDashboardStrategy extends HTMLElement {
  static async generate(config, hass) {
    const E = config.entities || {}, I = config.inverter || {}, R = config.rce || {};
    const views = [planView(E, I), editView(E, config.slots), decisionsView(E, I), rceView(R)].filter(Boolean);
    return { title: "Prelumo", views };
  }
}

if (!customElements.get("ll-strategy-dashboard-prelumo")) {
  customElements.define("ll-strategy-dashboard-prelumo", PrelumoDashboardStrategy);
}
